WITH order_summary AS (SELECT order_id, ROUND((100 * SUM(CASE WHEN method = 'paypal' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_paypal, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM payments GROUP BY order_id) SELECT o.customer_id, os.pct_paypal, os.status_list FROM orders o LEFT JOIN order_summary os ON o.id = os.order_id WHERE os.pct_paypal >= 67 ORDER BY o.customer_id DESC;
